/**
 * Lanza y explota dinamita con animación fluida, blindaje de obsidiana y actualización dirty.
 *
 * OPTIMIZACIÓN DIRTY Y RENDIMIENTO (60 FPS estables en 120+ TNTs):
 * 1. Actualización Dirty Desacoplada:
 *    - Las escrituras de voxeles acumulan una caja 2D dirty (_dirtyBox).
 *    - Un único bucle en requestAnimationFrame remalla los chunks modificados con mcRemeshAround
 *      EXACTAMENTE UNA VEZ por fotograma, eliminando cientos de mcFlushBuild cruzados que tiraban los FPS a 0.
 *    - Un lote global (beginBatch) engloba la ráfaga completa y se cierra con endBatch al finalizar.
 * 2. Visualización Garantizada de Fusión / Lava:
 *    - Todos los bloques destruidos pasan obligatoriamente por el estado visual de lava/fuego.
 * 3. Blindaje de Obsidiana:
 *    - La obsidiana no revienta nunca y ocluye radialmente la onda expansiva.
 *    - Pre-filtro y Set O(1) de obsidiana para coste computacional nulo cuando no hay obsidiana.
 * 4. Deduplicación Anti-Recursiva:
 *    - Cada bloque de TNT detona estrictamente una vez (_activeTNTCoords) sin recolocar bloques en cráteres.
 */
var o = (typeof opts !== 'undefined' && opts) ? opts : {};

// Estado global compartido
const _activeTNTCoords = (window._activeTNTCoords = window._activeTNTCoords || new Set());
const _meltingCells = (window._tntMeltingCells = window._tntMeltingCells || new Set());
const _obsIdCache = new Map();

let _dirtyBox = null;
let _tntBurstActive = false;
let _burstTimer = null;

function markDirty(x, z) {
    x = Math.floor(x);
    z = Math.floor(z);
    if (!_dirtyBox) {
        _dirtyBox = { x0: x, z0: z, x1: x, z1: z };
    } else {
        if (x < _dirtyBox.x0) _dirtyBox.x0 = x;
        else if (x > _dirtyBox.x1) _dirtyBox.x1 = x;
        if (z < _dirtyBox.z0) _dirtyBox.z0 = z;
        else if (z > _dirtyBox.z1) _dirtyBox.z1 = z;
    }
}

function tntRenderLoop() {
    if (_dirtyBox) {
        const { x0, z0, x1, z1 } = _dirtyBox;
        _dirtyBox = null;
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(x0, z0, x1, z1);
        } else if (typeof mcFlushBuild === 'function') {
            mcFlushBuild();
        }
    }

    if (_tntBurstActive && (window._tntActiveWaves || 0) > 0) {
        requestAnimationFrame(tntRenderLoop);
    } else {
        stopTNTBurst();
    }
}

function startTNTBurst() {
    if (!_tntBurstActive) {
        _tntBurstActive = true;
        if (typeof beginBatch === 'function') beginBatch();
        if (_burstTimer) clearTimeout(_burstTimer);
        _burstTimer = setTimeout(stopTNTBurst, 15000); // Límite de seguridad de 15s
        requestAnimationFrame(tntRenderLoop);
    }
}

function stopTNTBurst() {
    if (!_tntBurstActive) return;
    _tntBurstActive = false;
    if (_burstTimer) {
        clearTimeout(_burstTimer);
        _burstTimer = null;
    }
    if (_dirtyBox) {
        const { x0, z0, x1, z1 } = _dirtyBox;
        _dirtyBox = null;
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(x0, z0, x1, z1);
        }
    }
    if (typeof endBatch === 'function') {
        endBatch();
    }
    _meltingCells.clear();
}

function isObsidian(x, y, z) {
    if (typeof getVoxel !== 'function') return false;
    const v = getVoxel(x, y, z);
    if (!v) return false;

    if (typeof v === 'number') {
        const cached = _obsIdCache.get(v);
        if (cached !== undefined) return cached;
        let esObs = false;
        if (typeof mc !== 'undefined' && mc) {
            if (mc.inamovibleDoc && mc.inamovibleDoc[v]) {
                esObs = true;
            } else if (mc.blockKey && mc.blockKey[v]) {
                const k = String(mc.blockKey[v]).toLowerCase();
                if (k.includes('obsidian') || k.includes('obsidiana')) esObs = true;
            }
        }
        if (!esObs && typeof mcMatName === 'function') {
            const nm = mcMatName(v);
            if (nm && /obsidia/i.test(String(nm))) esObs = true;
        }
        _obsIdCache.set(v, esObs);
        return esObs;
    }

    if (typeof v === 'string') {
        return /obsidia/i.test(v);
    }
    return false;
}

// Trazado de rayo radial hacia el objetivo optimizado mediante Set O(1) de obsidiana
function isRayBlockedByObsidian(cx, cy, cz, tx, ty, tz, obsSet) {
    if (!obsSet || obsSet.size === 0) return false;
    const dx = tx - cx;
    const dy = ty - cy;
    const dz = tz - cz;
    const distSq = dx * dx + dy * dy + dz * dz;
    if (distSq <= 1) return false;

    const dist = Math.sqrt(distSq);
    const step = 0.25;
    const numSteps = Math.floor(dist / step);
    let lastX = cx, lastY = cy, lastZ = cz;

    for (let i = 1; i < numSteps; i++) {
        const t = (i * step) / dist;
        const vx = Math.round(cx + dx * t);
        const vy = Math.round(cy + dy * t);
        const vz = Math.round(cz + dz * t);

        if (vx === cx && vy === cy && vz === cz) continue;
        if (vx === tx && vy === ty && vz === tz) break;
        if (vx === lastX && vy === lastY && vz === lastZ) continue;
        lastX = vx; lastY = vy; lastZ = vz;

        if (obsSet.has(vx + ',' + vy + ',' + vz)) {
            return true;
        }
    }
    return false;
}

function throwAndExplodeTNT(startX, startY, startZ, options = {}) {
    const radius = options.radius || 4;
    const force = options.force || 1.0;
    const fuseTime = options.fuseTimeMs != null ? options.fuseTimeMs : 2000;
    const tntMat = options.tntMat || 'hab:likelava';
    const isChained = !!options.isChained;

    const tntKey = Math.floor(startX) + ',' + Math.floor(startY) + ',' + Math.floor(startZ);
    if (_activeTNTCoords.has(tntKey)) return;
    _activeTNTCoords.add(tntKey);

    const endY = startY;
    // Solo colocar mecha física inicial si es lanzamiento fresco del jugador
    if (!isChained && typeof setVoxel === 'function') {
        setVoxel(startX, endY, startZ, tntMat);
        markDirty(startX, startZ);
        if (typeof mcRemeshAround === 'function') {
            mcRemeshAround(startX, startZ);
        }
    }
    console.log(`🧨 Dinamita lanzada a (${startX}, ${endY}, ${startZ}). Mecha: ${fuseTime}ms`);

    setTimeout(() => {
        executeSphericalExplosion(startX, endY, startZ, radius, force, options);
        _activeTNTCoords.delete(tntKey);
    }, fuseTime);
}

function executeSphericalExplosion(centerX, centerY, centerZ, radius, force, options = {}) {
    const startTime = performance.now();
    const waveMs = options.waveMs != null ? options.waveMs : 40;
    const showFire = options.fire !== false;
    const fireMat = options.fireMat || 'hormig-n-naranja';

    const cx = Math.floor(centerX);
    const cy = Math.floor(centerY);
    const cz = Math.floor(centerZ);

    const radiusSq = radius * radius;
    const canRead = typeof getVoxel === 'function';

    // 0. Pre-filtro rápido: buscar si existe obsidiana en el radio de esta explosión
    const obsidianFound = [];
    for (let x = cx - radius; x <= cx + radius; x++) {
        for (let y = cy - radius; y <= cy + radius; y++) {
            for (let z = cz - radius; z <= cz + radius; z++) {
                const dx = x - cx, dy = y - cy, dz = z - cz;
                if (dx * dx + dy * dy + dz * dz > radiusSq) continue;
                if (isObsidian(x, y, z)) {
                    obsidianFound.push([x, y, z]);
                }
            }
        }
    }
    const hasObsidian = obsidianFound.length > 0;
    const obsSet = hasObsidian ? new Set(obsidianFound.map(([ox, oy, oz]) => ox + ',' + oy + ',' + oz)) : null;

    // 1. PRECÁLCULO: agrupar en anillos concéntricos
    const rings = [];
    const avisos = [];
    let toDestroy = 0;

    for (let x = cx - radius; x <= cx + radius; x++) {
        for (let y = cy - radius; y <= cy + radius; y++) {
            for (let z = cz - radius; z <= cz + radius; z++) {

                const dx = x - cx, dy = y - cy, dz = z - cz;
                const distanceSq = dx * dx + dy * dy + dz * dz;
                if (distanceSq > radiusSq) continue;

                const k = x + ',' + y + ',' + z;
                if (_meltingCells.has(k)) continue;

                if (canRead && !getVoxel(x, y, z)) continue;

                if (isObsidian(x, y, z)) continue;

                if (hasObsidian && isRayBlockedByObsidian(cx, cy, cz, x, y, z, obsSet)) continue;

                const impactPower = 1.0 - (distanceSq / radiusSq);
                const effectiveImpact = impactPower * force;

                if (effectiveImpact > 0.5 || Math.random() < effectiveImpact) {
                    const d = Math.floor(Math.sqrt(distanceSq));
                    (rings[d] || (rings[d] = [])).push([x, y, z]);
                    _meltingCells.add(k);

                    if (!_activeTNTCoords.has(k)) {
                        const avisa = (typeof game !== 'undefined' && game.bloques && typeof game.bloques.avisoDeRotura === 'function')
                            ? game.bloques.avisoDeRotura(x, y, z)
                            : null;
                        if (avisa) (avisos[d] || (avisos[d] = [])).push(avisa);
                    }
                    toDestroy++;
                }
            }
        }
    }

    if (toDestroy === 0) return;

    console.log(`💥 Detonación en (${cx}, ${cy}, ${cz}). Radio ${radius}. ${toDestroy} bloques.`);

    // Iniciar ráfaga y bucle dirty global desacoplado
    window._tntActiveWaves = (window._tntActiveWaves || 0) + 1;
    startTNTBurst();

    let prevFire = null;
    let prevAvisos = null;

    // 2. ANIMACIÓN CON ACTUALIZACIÓN DIRTY
    function wave(d) {
        let dar = [];

        // Apagar el frente anterior: lava -> aire (queda el cráter)
        if (prevFire) {
            for (const [x, y, z] of prevFire) {
                setVoxel(x, y, z, 0);
                markDirty(x, z);
                _meltingCells.delete(x + ',' + y + ',' + z);
            }
            dar = prevAvisos || [];
        }

        // Anillo actual: pintar frente de lava (incluso el último anillo)
        if (d < rings.length) {
            const cells = rings[d] || [];
            if (showFire && cells.length > 0) {
                for (const [x, y, z] of cells) {
                    setVoxel(x, y, z, fireMat);
                    markDirty(x, z);
                }
                prevFire = cells;
                prevAvisos = avisos[d] || null;
            } else {
                for (const [x, y, z] of cells) {
                    setVoxel(x, y, z, 0);
                    markDirty(x, z);
                    _meltingCells.delete(x + ',' + y + ',' + z);
                }
                prevFire = null;
                prevAvisos = null;
                dar = dar.concat(avisos[d] || []);
            }
        } else {
            prevFire = null;
            prevAvisos = null;
        }

        // Despachar avisos alRomper con las celdas ya en aire
        for (const avisa of dar) avisa();

        if (d < rings.length) {
            setTimeout(() => wave(d + 1), waveMs);
        } else {
            window._tntActiveWaves = Math.max(0, (window._tntActiveWaves || 1) - 1);
            const ms = (performance.now() - startTime).toFixed(2);
            console.log(`🔥 Explosión completa: ${toDestroy} bloques en ${ms}ms.`);
        }
    }

    wave(0);
}

if (typeof game !== 'undefined') {
    game.throwAndExplodeTNT = throwAndExplodeTNT;
    game.executeSphericalExplosion = executeSphericalExplosion;
}
if (typeof window !== 'undefined') {
    window.throwAndExplodeTNT = throwAndExplodeTNT;
    window.executeSphericalExplosion = executeSphericalExplosion;
}

// Hot-patch en game.bloques para reacciones en cadena limpias con onda visible y dirty updates
if (typeof game !== 'undefined' && game.bloques && typeof game.bloques.define === 'function') {
    const tntConfig = {
        nota: 'Sorpresa: explota (protegido por obsidiana)!',
        alRomper: function (c) {
            const tntKey = Math.floor(c.x) + ',' + Math.floor(c.y) + ',' + Math.floor(c.z);
            if (_activeTNTCoords.has(tntKey)) return;
            _activeTNTCoords.add(tntKey);

            const delay = 25 + Math.floor(Math.random() * 25);
            setTimeout(() => {
                executeSphericalExplosion(c.x, c.y, c.z, 6, 1.5, {
                    waveMs: 40,
                    fireMat: 'hormig-n-naranja',
                    isChained: true
                });
                _activeTNTCoords.delete(tntKey);
            }, delay);
        }
    };
    try {
        game.bloques.define('asset:assets/tnt.vox.json', tntConfig);
        game.bloques.define('hab:tnt', tntConfig);
        game.bloques.define('tnt', tntConfig);
    } catch (e) {}
}

// Hot-patch para la tecla T al apuntar
if (typeof game !== 'undefined' && typeof game.onKey === 'function') {
    game.onKey('t', () => {
        if (typeof game.aim !== 'function') return;
        const aim = game.aim();
        if (!aim) return;
        throwAndExplodeTNT(...aim, {
            radius: 8,
            force: 1.5,
            fuseTimeMs: 400,
            tntMat: 'lava',
            waveMs: 40,
            fireMat: 'hormig-n-naranja'
        });
    });
}

// Si se invocó con parámetros directos (ej. game.snippet('explosion-tnt-obsidiana', c))
if (o && typeof o.x === 'number' && typeof o.y === 'number' && typeof o.z === 'number') {
    const tntKey = Math.floor(o.x) + ',' + Math.floor(o.y) + ',' + Math.floor(o.z);
    if (!_activeTNTCoords.has(tntKey)) {
        _activeTNTCoords.add(tntKey);
        const isChained = !!(o.cfg && o.cfg.nota);
        if (isChained) {
            const delay = 25 + Math.floor(Math.random() * 25);
            setTimeout(() => {
                executeSphericalExplosion(o.x, o.y, o.z, o.radius || 6, o.force || 1.5, {
                    waveMs: o.waveMs || 40,
                    fireMat: o.fireMat || 'hormig-n-naranja',
                    isChained: true
                });
                _activeTNTCoords.delete(tntKey);
            }, delay);
        } else {
            throwAndExplodeTNT(o.x, o.y, o.z, {
                radius: o.radius || 8,
                force: o.force || 1.5,
                fuseTimeMs: o.fuseTimeMs != null ? o.fuseTimeMs : 400,
                tntMat: o.tntMat || 'lava',
                waveMs: o.waveMs || 40,
                fireMat: o.fireMat || 'hormig-n-naranja'
            });
        }
    }
} else if (typeof toast === 'function') {
    toast('🧨 TNT optimizada: Actualización dirty a 60 FPS y blindaje de obsidiana');
}

return { throwAndExplodeTNT, executeSphericalExplosion };
